const allItems = $input.all().map(item => item.json);
return [{
  json: {
    gastos: JSON.stringify(allItems, null, 2),
    total_registros: allItems.length
  }
}];

let text = $input.first().json.text || '';

// Extraer HTML si viene envuelto en markdown ```html ... ```
const match = text.match(/```html?\s*([\s\S]*?)```/);
if (match) {
  text = match[1].trim();
}

// Si aún tiene texto antes del <!DOCTYPE, cortarlo
const docIndex = text.indexOf('<!DOCTYPE');
if (docIndex > 0) {
  text = text.substring(docIndex);
}

// Si tiene texto después de </html>, cortarlo
const htmlEnd = text.lastIndexOf('</html>');
if (htmlEnd !== -1) {
  text = text.substring(0, htmlEnd + 7);
}

return [{ json: { html: text } }];
